// UMBRELLA: ACCOUNTING CALCULATORS (Daily & Month-End)
// ═══════════════════════════════════════════════════════════════════

function AccountingCalculators() {
  const [activeCalc, setActiveCalc] = useState('depreciation');

  const calcs = [
    { id: 'depreciation', label: 'Depreciation', icon: '📉', desc: 'SL · DDB · SYD · MACRS · Sec 179', component: Depreciation },
    { id: 'prepaid',      label: 'Amortization / Prepayment', icon: '🧮', desc: 'Prepaid, intangible, deferred revenue', component: PrepaidAmortization },
    { id: 'loan',         label: 'Loan Amortization', icon: '🏦', desc: 'Full payment schedule + extra payments', component: LoanAmortization },
    { id: 'salestax',     label: 'Sales Tax', icon: '🧾', desc: 'Gross-up or extract tax from total', component: SalesTaxCalculator },
    { id: 'markup',       label: 'Markup vs Margin', icon: '📊', desc: 'Pricing math · markup ≠ margin', component: MarkupMarginCalculator },
    { id: 'breakeven',    label: 'Break-Even', icon: '🎯', desc: 'Units & revenue to cover costs', component: BreakEvenCalculator },
    { id: 'mileage',      label: 'Mileage Reimbursement', icon: '🚗', desc: 'IRS standard mileage by trip', component: MileageCalculator },
  ];

  const active = calcs.find(c => c.id === activeCalc);
  const ActiveComponent = active.component;

  return (
    <div>
      <SectionHead eyebrow="Daily & Month-End · Tool" title="Accounting Calculators" desc="A 7-in-one calculator suite for daily bookkeeping work. Every calculation a US bookkeeper makes regularly — depreciation, amortization schedules, sales tax, markup vs margin, break-even, mileage reimbursement, loan payments — all in one place." />

      {/* Calculator selector */}
      <div className="grid grid-cols-2 md:grid-cols-4 lg:grid-cols-7 gap-2 mt-6 mb-6">
        {calcs.map(c => {
          const isActive = activeCalc === c.id;
          return (
            <button key={c.id} onClick={() => setActiveCalc(c.id)}
              className={`p-3 rounded-2xl transition text-left ${isActive ? 'text-white shadow-lg' : 'bg-white border border-slate-200 hover:border-blue-300'}`}
              style={isActive ? { background: `linear-gradient(135deg, ${ROYAL} 0%, ${CYAN} 100%)` } : {}}>
              <div className="text-xl mb-1">{c.icon}</div>
              <div className={`text-xs font-bold leading-tight mb-0.5 ${isActive ? 'text-white' : 'text-slate-800'}`}>{c.label}</div>
              <div className={`text-[9px] leading-tight ${isActive ? 'text-blue-100' : 'text-slate-500'}`}>{c.desc}</div>
            </button>
          );
        })}
      </div>

      {/* Active calculator hero */}
      <div className="p-5 rounded-2xl text-white shadow-lg mb-5" style={{ background: `linear-gradient(135deg, ${INK.navy} 0%, ${ROYAL} 60%, ${CYAN} 100%)` }}>
        <div className="flex items-center gap-3">
          <div className="text-3xl">{active.icon}</div>
          <div>
            <div className="text-[10px] uppercase tracking-[0.3em] font-bold text-blue-200">Active Calculator</div>
            <div style={{ fontFamily: fontDisplay }} className="text-2xl font-bold">{active.label}</div>
            <div className="text-xs text-blue-100">{active.desc}</div>
          </div>
        </div>
      </div>

      {/* Active calculator content */}
      <div>
        <ActiveComponent />
      </div>
    </div>
  );
}



