                <select className="w-full px-3 py-2 rounded-lg border border-slate-300 text-sm bg-white" value={revenueRange} onChange={e => setRevenueRange(e.target.value)}>
                  <option value="">— Select range —</option>
                  {revenueRanges.map(r => <option key={r} value={r}>{r}</option>)}
                </select>
